"""Command-line adapter for the wordstat package."""

from __future__ import annotations

import argparse
import json
import sys
from collections.abc import Sequence

from .core import WordStat, analyze_text


def _positive_int(value: str) -> int:
    """Parse a positive integer for the --top option."""

    try:
        parsed = int(value)
    except ValueError as error:
        raise argparse.ArgumentTypeError(
            f"invalid positive integer value: {value!r}"
        ) from error

    if parsed < 1:
        raise argparse.ArgumentTypeError(
            f"invalid positive integer value: {value!r}"
        )
    return parsed


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="wordstat", allow_abbrev=False)
    parser.add_argument("--json", action="store_true")
    parser.add_argument("--top", type=_positive_int, default=3)
    parser.add_argument("file", metavar="FILE")
    return parser


def _configure_streams() -> None:
    sys.stdout.reconfigure(encoding="utf-8", newline="\n")
    sys.stderr.reconfigure(encoding="utf-8", newline="\n")


def _read_text(path: str) -> str:
    """Read and strictly decode one file without newline translation."""

    with open(path, "rb") as stream:
        return stream.read().decode("utf-8-sig")


def _render_text(result: WordStat) -> str:
    top = " ".join(f"{entry.word}={entry.count}" for entry in result.top)
    top_line = f"top: {top}" if top else "top:"
    return (
        f"lines: {result.lines}\n"
        f"words: {result.words}\n"
        f"chars: {result.chars}\n"
        f"{top_line}\n"
    )


def _render_json(result: WordStat) -> str:
    payload = {
        "lines": result.lines,
        "words": result.words,
        "chars": result.chars,
        "top": [
            {"word": entry.word, "count": entry.count} for entry in result.top
        ],
    }
    return json.dumps(payload) + "\n"


def _error(message: str) -> int:
    sys.stderr.write(f"wordstat: error: {message}\n")
    return 1


def main(argv: Sequence[str] | None = None) -> int:
    """Run the wordstat command and return its process status."""

    _configure_streams()
    parser = _build_parser()

    try:
        args = parser.parse_args(argv)
        try:
            text = _read_text(args.file)
        except OSError:
            sys.stderr.write(f"wordstat: error: {args.file}: cannot read file\n")
            return 3
        except UnicodeDecodeError:
            sys.stderr.write(f"wordstat: error: {args.file}: not valid UTF-8\n")
            return 3

        result = analyze_text(text, top_n=args.top)
        output = _render_json(result) if args.json else _render_text(result)
        sys.stdout.write(output)
    except Exception:
        return _error("internal error")

    return 0
